  if(v.n!=null) return {info:true, msg:'Typ een geheel getal, geen breuk.'};
  if(/[.,]/.test(t)) return {info:true, msg:'Typ een geheel getal, zonder komma.'};
  const x = rdZ(v); if(x==null) return {info:true, msg:'Typ enkel een geheel getal.'};
