    s += `<path class="as-spk ${sp.cls||''}${sp.nieuw ? ' nieuw' : ''}${sp.vl ? ' vl' : ''}" d="M${fx(x2)} ${y-7} l${-dir*9} -7 l${dir*2} 9z"/>`;
