/* som zonder haakjes: −5 + 8 − 3 */
const kaalS = t => t.map((x, i) => i ? (x<0 ? ' − ' : ' + ') + dz(Math.abs(x)) : zS(x)).join('');
const kleurS = t => t.map((x, i) => `<span class="m5-term ${x<0 ? 'neg' : 'pos'}">${i ? (x<0 ? '− ' : '+ ') + dz(Math.abs(x)) : zS(x)}</span>`).join(' ');
