FT.mix = schriftKaart('Gemengd', 2, R => R.shuffle(FT_GEN.optel.concat(FT_GEN.maal, FT_GEN.volg)).map(f => ftMaak(R, f)).filter(x => x[1]), 3);
FT.diep = ftKaart('Lange opgaven', 3, 'diep', 3);
