      if(typeof v==='number' && dec!=null && dec>0){ let t=nf(v,dec); const k=t.indexOf(','); const have = k<0?0:t.length-k-1; if(have<dec) t = (k<0? t+',' : t) + '0'.repeat(dec-have); td.textContent = t; }
