  const L = [[`Om 7 uur 's ochtends is het ${zS(t)} °C. Tegen 15 uur is het ${d} graden warmer. Hoeveel graden is het om 15 uur?`, `${zS(t)} + ${d}`, '°C'],
    [`Een lift vertrekt in de parking op niveau ${zS(v)}. Hij stijgt ${s} verdiepingen en daalt dan ${z} verdiepingen. Op welk niveau stopt de lift?`, `${zS(v)} + ${s} − ${z}`, '']];
