  const L = R.shuffle([[`${zS(a)} + ${c}`, a + c], [`${zS(-c)} − ${zP(e)}`, -c - e], [`${zS(e)} · ${zP(-d)}`, e*-d], [`${zS(-f*k)} : ${k}`, -f], [`−|${zS(m)}|`, -Math.abs(m)], [`${zS(-d)} − ${c}`, -d - c]]);
