E1.code = pexV('Kraak de code', 2.5, 'Het hangslot van de fietsenstalling heeft een code van vier cijfers <b>A B C D</b>. Zoek elk cijfer.', (b, st, save) => {
  const R = makeR(st);
  const [x, y] = R.pick([[91, 7], [85, 5], [119, 7], [161, 7], [65, 5]]);
  const a = R.int(3, 9), c = R.int(2, 7);
  const n = R.pick([[12, 6], [18, 6], [16, 5], [20, 6], [28, 6]]);
  const C = [
    [`A is de kleinste priemfactor van ${x}.`, y],
    [`B is het aantal delers van ${n[0]}.`, n[1]],
    [`C = ${zS(-a*c)} : ${zP(-a)}`, c],
    [`D is het tegengestelde van ${zS(-((a + c) % 10 || 4))}.`, (a + c) % 10 || 4]];
  C.forEach(([t, T], i) => qBlock(b, st, save, 'c' + i, { html:`${t} &nbsp; <b>${'ABCD'[i]} =</b> [[0:xs]]`, mode:'numeric', pts:.5, check:pexIs(T) }));
  qBlock(b, st, save, 'code', { nr:'', html:'De code is [[0]]', mode:'numeric', pts:.5, check:v => ({ok:String(v[0]).replace(/\s/g, '')===C.map(c => c[1]).join('')}) });
  st._show = C.map((c, i) => 'ABCD'[i] + ' = ' + c[1]).join(', ') + ' · code ' + C.map(c => c[1]).join('');
}, null, 'Module 1 en Module 5');

