  const G = R.shuffle([{w:-v[0], h:zS(-v[0])}, {w:v[1], h:`|${zS(-v[1])}|`}, {w:v[2], h:`−(${zS(-v[2])})`}, {w:-v[3], h:zS(-v[3])}, {w:0, h:'0'}, {w:-v[4], h:`−|${v[4]}|`}]);
