E1.hoekreken = pexV('Hoeken berekenen', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.rekenC).build(b, st, save, key), null, 'Module 2 › Hoeken berekenen');
E1.centrum = pexV('Centrummaten', 3, '', (b, st, save) => {
  const R = makeR(st); const n = 9; const v = pexMetModus(R, n, 14, 34);
  const s = v.slice().sort((p, q) => p - q), gem = v.reduce((p, x) => p + x, 0)/n, med = s[4]; const f = {}; v.forEach(x => f[x] = (f[x]||0) + 1); const mo = +Object.keys(f).find(k => f[k]===Math.max(...Object.values(f)));
  const [l, r] = pexNaast(b);
  l.append(el('div', 'q-text block', `Bij de les LO telt de leerkracht hoeveel keer elke leerling in 30 seconden over het springtouw springt:<div class="m5-groot" style="margin-top:.5rem">${v.join(' &nbsp; ')}</div>`));
  qBlock(r, st, save, 'g', { nr:'a)', html:'Het gemiddelde (rond af op 0,1) is [[0:xs]]', pts:1, check:pexIs(Math.round(gem*10)/10, .001) });
  qBlock(r, st, save, 'm', { nr:'b)', html:'De mediaan is [[0:xs]]', mode:'numeric', pts:.75, check:pexIs(med) });
  qBlock(r, st, save, 'o', { nr:'c)', html:'De modus is [[0:xs]]', mode:'numeric', pts:.5, check:pexIs(mo) });
  qBlock(r, st, save, 'v', { nr:'d)', html:'De variatiebreedte is [[0:xs]]', mode:'numeric', pts:.75, check:pexIs(s[n-1] - s[0]) });
  st._show = `geordend: ${s.join(', ')} · gemiddelde ${pexKomma(gem, 1)} · mediaan ${med} · modus ${mo} · variatiebreedte ${s[n-1]} − ${s[0]} = ${s[n-1] - s[0]}`;
}, null, 'Module 3 › Het gemiddelde, De mediaan, Modus en Variatiebreedte');
E1.mislei = pexV('Misleidende grafiek', 2, '', (b, st, save, key) => {
  const R = makeR(st); const item = M3.POOL[6].fixed[R.pick([0, 2])];
  viaMod(M3, item).build(b, st, save, key); st._show = item.show;
}, null, 'Module 3 › Misleidende grafieken');
E1.toestel = pexV('Rekentoestel', 1, 'Bereken met je rekentoestel. Schrijf enkel de uitkomst.', (b, st, save) => {
  const R = makeR(st); let a, c, d, e, t;
  do{ a = -R.int(200, 900); c = R.int(100, 999); d = R.int(11, 19); e = R.int(2, 9); t = (a + c)*d; }while(t % e!==0 || a + c===0);
  const T = -t/e, E = `−(${zS(a)} + ${c}) · ${d} : ${zP(e)}`;
  mQ(b, st, save, 't', { html:`<span class="m5-opg">${E}</span> ${isq} {{u:a}}`, check:V => chkG(V.a, T) });
  st._show = `${E} = ${zS(T)}`;
}, null, 'Module 3 › Met het rekentoestel');
E1.kgv = pexV('Vraagstuk', 2, '', (b, st, save) => {
  const R = makeR(st); const [p, q] = R.pick([[12, 18], [15, 20], [10, 25], [12, 20], [14, 21]]); const k = pexKgv(p, q); const u = R.int(7, 9);
  const eind = u*60 + k; const hh = Math.floor(eind/60), mm = eind % 60;
  b.append(el('div', 'q-text block', `Aan het station vertrekt bus 3 om de ${p} minuten en bus 7 om de ${q} minuten. Om ${u}.00 uur vertrekken ze samen.`));
  qBlock(b, st, save, 'a', { nr:'a)', html:'Na hoeveel minuten vertrekken ze opnieuw samen? [[0:xs]] minuten', mode:'numeric', pts:1, check:pexIs(k) });
  qBlock(b, st, save, 'b', { nr:'b)', html:'Om hoe laat is dat? [[0:xs]] uur [[1:xs]]', mode:'numeric', pts:1, check:pexAllen([hh, mm]) });
  st._show = `kgv(${p}, ${q}) = ${k} minuten · om ${hh}.${String(mm).padStart(2, '0')} uur`;
}, null, 'Module 1 › Vraagstukken');
E1.prijs = pexV('Vraagstuk met een prijslijst', 2.5, '', (b, st, save) => {
  const R = makeR(st);
  const PR = [['volwassene', 14.5], ['kind van 4 tot 12 jaar', 9.5], ['kind jonger dan 4 jaar', 0], ['huur van een bolderkar', 6], ['portie frietjes', 3.5]];
  const nv = R.int(2, 4), nk = R.int(2, 4), nb = R.int(1, 2), nf = nv + nk + nb;
  const T = nv*14.5 + nk*9.5 + 6 + nf*3.5; const B = Math.ceil(T/50)*50 + (T % 50===0 ? 50 : 0);
  const [l, r] = pexNaast(b);
  l.append(el('div', '', `<table class="pex-tabel"><tr><th class="l" colspan="2">Dierenpark De Zonnebloem</th></tr>${PR.map(([n, p]) => `<tr><td class="l">${n}</td><td>${p ? pexEuro(p) : 'gratis'}</td></tr>`).join('')}</table>`));
  r.append(el('div', 'q-text block', `De familie Claes gaat naar het dierenpark met ${nv} volwassenen, ${nk} kinderen van 4 tot 12 jaar en ${nb} ${nb===1 ? 'kind' : 'kinderen'} jonger dan 4 jaar. Ze huren één bolderkar en iedereen eet een portie frietjes.`));
  qBlock(r, st, save, 'a', { nr:'a)', html:'Hoeveel betalen ze in totaal? € [[0:xs]]', pts:1.5, check:pexIs(T, .001) });
  qBlock(r, st, save, 'b', { nr:'b)', html:`Ze betalen met ${B/50} ${B===50 ? 'briefje' : 'briefjes'} van 50 euro. Hoeveel krijgen ze terug? € [[0:xs]]`, pts:1, check:pexIs(B - T, .001) });
  st._show = `${nv} · 14,50 + ${nk} · 9,50 + 6 + ${nf} · 3,50 = ${pexEuro(T)} · terug: ${pexEuro(B - T)}`;
}, null, 'Module 5 › Alles door elkaar en vraagstukken');
PEX.examens.push({
  deel1:[E1.talstelsel, E1.opsomming, E1.symbolen, E1.venn, E1.priem, E1.situaties, E1.reken, E1.volgorde, E1.coord, E1.code],
  deel2:[E1.orde, E1.begrip, E1.midden, E1.hoekmeten, E1.hoekreken, E1.centrum, E1.mislei, E1.toestel, E1.kgv, E1.prijs]
});


/* ===== pex_20_examen2.js ===== */
/* ============================================================
   PROEFEXAMEN 2
   ============================================================ */
const E2 = {};
/* ---------- Deel 1 ---------- */
E2.impl = pexV('Implicatiepijl', 2, 'Is de uitspraak juist of fout? Geef bij fout een tegenvoorbeeld.', (b, st, save) => {
  const R = makeR(st);
  const P = [
    ['x ∈ 6ℕ ⇒ x ∈ 3ℕ', 'juist', 'Elk veelvoud van 6 is ook een veelvoud van 3.'],
    ['x ∈ 3ℕ ⇒ x ∈ 6ℕ', 'fout', '', {pre:x => Number.isInteger(x) && x>=0 && x % 3===0, con:x => Number.isInteger(x) && x>=0 && x % 6===0, preT:'x ∈ 3ℕ', conT:'x ∈ 6ℕ'}],
    ['x ∈ ℤ ⇒ x ∈ ℕ', 'fout', '', {pre:x => Number.isInteger(x), con:x => Number.isInteger(x) && x>=0, preT:'x ∈ ℤ', conT:'x ∈ ℕ'}],
    ['x &lt; −3 ⇒ x &lt; 0', 'juist', 'Een getal kleiner dan −3 is zeker negatief.'],
    ['x &gt; −2 ⇒ x &gt; 0', 'fout', '', {pre:x => x > -2, con:x => x > 0, preT:'x > −2', conT:'x > 0'}],
    ['x ∈ del 9 ⇒ x ∈ del 18', 'juist', 'Elke deler van 9 is ook een deler van 18.'],
    ['x is even ⇒ x ∈ 4ℕ', 'fout', '', {pre:x => Number.isInteger(x) && x>=0 && x % 2===0, con:x => Number.isInteger(x) && x>=0 && x % 4===0, preT:'x is even', conT:'x ∈ 4ℕ'}]];
  const juist = R.shuffle(P.filter(x => x[1]==='juist'))[0], fout = R.shuffle(P.filter(x => x[1]==='fout'))[0];
  const L = R.shuffle([juist, fout]);
  viaMod(M1, {build:(bb, ss, sv) => L.forEach((x, i) => M1.qBlock(bb, ss, sv, 'i' + i, Object.assign({nr:'ab'[i] + ')'}, M1.implQ(...x))))}).build(b, st, save);
  st._show = L.map(x => `${x[0]}: ${x[1]}${x[1]==='fout' ? ' (een tegenvoorbeeld)' : ''}`).join(' · ');
}, null, 'Module 1 › Implicatiepijl');
E2.deelbaar = pexV('Deelbaarheid', 2.5, 'Duid bij elk getal <b>alle</b> getallen aan waardoor het deelbaar is.', (b, st, save) => {
  const R = makeR(st); const D = [2, 3, 4, 5, 6, 9, 10];
  const maak = () => { let n; do{ n = R.int(1000, 99999); }while(D.filter(d => n % d===0).length < 2); return n; };
  const N = [maak(), maak()];
  N.forEach((n, i) => multiKeuze(b, st, save, 'd' + i, { nr:'ab'[i] + ')', html:`<span class="m5-groot">${dz(String(n))}</span> is deelbaar door …`, opts:D.map(d => [String(d), String(d), n % d===0]) }));
  st._show = N.map(n => `${dz(String(n))}: ${D.filter(d => n % d===0).join(', ')}`).join(' · ');
}, null, 'Module 1 › Vervang x en Deling met rest');
E2.kleur = pexV('Venndiagram kleuren', 1.5, '', (b, st, save, key) => {
  const R = makeR(st);
  const K = [['A ∩ B ∩ C', (a, c, d) => a && c && d, 'het deel dat in A, B én C ligt'], ['(A ∩ B) \\ C', (a, c, d) => a && c && !d, 'het deel van A ∩ B dat niet in C ligt'],
    ['C \\ (A ∪ B)', (a, c, d) => d && !a && !c, 'het deel van C buiten A en B'], ['(A ∪ C) ∩ B', (a, c, d) => (a || d) && c, 'het deel van B dat ook in A of in C ligt']];
  const [l, f, s] = R.pick(K); const item = M1.PQ.kleur(3, l, f, s);
  viaMod(M1, item).build(b, st, save, key); st._show = s;
}, null, 'Module 1 › Venn: kleuren');
E2.pf = pexV('Priemfactoren gebruiken', 2, '', (b, st, save) => {
  const R = makeR(st); const F = R.pick([[2, 2, 3, 5, 7], [2, 3, 3, 5, 11], [2, 2, 2, 3, 7], [3, 3, 5, 7, 2]]); const n = F.reduce((p, x) => p*x, 1);
  const kand = R.shuffle([4, 6, 8, 9, 10, 12, 14, 15, 18, 21, 25, 27, 35, 49]).slice(0, 4);
  b.append(el('div', 'q-text block', `Gegeven: <b>a = ${F.slice().sort((p, q) => p - q).join(' · ')}</b>. Reken a niet uit. Is a deelbaar door …`));
  const g = el('div', 'm4-items'); b.append(g);
  kand.forEach((d, i) => { const row = el('div', 'm4-wn'); g.append(row); qChoice(row, st, save, 'k' + i, { nr:'abcd'[i] + ')', html:`<span class="m5-groot">${d}?</span> <small>(${d} = ${pexPfT(d)})</small>`, opts:[['j', 'ja'], ['n', 'nee']], ans:n % d===0 ? 'j' : 'n' }); });
  st._show = kand.map(d => `${d}: ${n % d===0 ? 'ja' : 'nee'}`).join(' · ') + ` (a deelbaar door d als alle priemfactoren van d in a zitten)`;
}, null, 'Module 1 › Priemfactoren');
E2.ggd = pexV('Vraagstuk', 2, '', (b, st, save, key) => {
  const R = makeR(st); const [p, q] = R.pick([[48, 72], [60, 84], [45, 75], [54, 90], [36, 60]]); const g = ggd(p, q);
  const item = M1.probQ({text:`Joke heeft een rood lint van ${p} cm en een blauw lint van ${q} cm. Ze knipt beide linten in stukken die allemaal even lang zijn, zo lang mogelijk, zonder dat er iets overblijft. <b>Hoe lang is één stuk?</b>`, ans:'ggd', nums:[p, q], si:[0], ai:[1], ansHtml:'[[1:xs]]', ansCheck:M1.numIs(g), unit:'cm', mode:'numeric', why:'Je zoekt de grootste lengte die in beide linten past: dat is een gemeenschappelijke deler.', sol:''});
  viaMod(M1, {build:(bb, ss, sv) => M1.qBlock(bb, ss, sv, 'v', item)}).build(b, st, save, key);
  st._show = `ggd(${p}, ${q}) = ${g} cm`;
}, null, 'Module 1 › Vraagstukken');
E2.teken = pexV('Positief, negatief of nul?', 2, 'Reken niet uit. Is het resultaat positief, negatief of nul?', (b, st, save) => {
  const R = makeR(st); const n = () => R.int(2, 19);
  const L = R.shuffle([
    (() => { const k = R.pick([2, 3]); const f = Array.from({length:4}, (_, i) => (i < k ? -1 : 1)*n()); const s = R.shuffle(f); return [s.map((x, i) => i ? zP(x) : zS(x)).join(' · '), k % 2 ? '-' : '+']; })(),
    (() => { const f = [-n(), n(), 0, -n()]; return [R.shuffle(f).map((x, i) => i ? zP(x) : zS(x)).join(' · '), '0']; })(),
    (() => { const a = R.int(100, 999), c = R.int(1000, 2000); return [`${zS(-a)} − ${dz(String(c))}`, '-']; })(),
    (() => { const a = R.int(10, 99); return [`${zS(-a)} − ${zP(-a - R.int(1, 30))}`, '+']; })()]);
  const g = el('div', 'm4-items een'); b.append(g);
  L.forEach(([h, a], i) => qChoice(g, st, save, 't' + i, { nr:'abcd'[i] + ')', html:`<span class="m5-groot">${h}</span>`, opts:PNN, ans:a }));
  st._show = L.map(([h, a]) => `${'abcd'[L.findIndex(x => x[0]===h)]}) ${{'+':'positief', '-':'negatief', '0':'nul'}[a]}`).join(' · ');
}, null, 'Module 5 › Vermenigvuldigen');
E2.ontbreek = pexV('Het ontbrekende getal', 3, 'Welk getal moet er op de plaats van het vakje staan?', (b, st, save) => {
  const R = makeR(st); const x = () => nz(R, -40, 40), k = () => R.int(2, 9)*R.sign();
  const a = x(), c = x(), d = k(), e = k(), f = x(), q = k(), m = k(), r = k();
  const L = R.shuffle([[`{{u:a}} + ${zP(c)} ${isq} ${zS(a + c)}`, a], [`${zS(f)} − {{u:a}} ${isq} ${zS(f - c)}`, c], [`{{u:a}} · ${zP(e)} ${isq} ${zS(d*e)}`, d],
    [`${zS(q*m)} : {{u:a}} ${isq} ${zS(q)}`, m], [`{{u:a}} − ${zP(r)} ${isq} ${zS(f - r)}`, f], [`{{u:a}} : ${zP(e)} ${isq} ${zS(r)}`, r*e]]);
  pexRij(b, 6, (g, i, nr) => { const [h, T] = L[i]; mQ(g, st, save, 'o' + i, { nr, html:h, check:V => chkG(V.a, T) }); });
  st._show = L.map(([h, T], i) => `${'abcdef'[i]}) ${zS(T)}`).join(' · ');
}, null, 'Module 5 › Optellen tot Delen');
E2.eig = pexV('Eigenschappen', 2, 'Welke eigenschap wordt gebruikt?', (b, st, save) => {
  const R = makeR(st); const a = nz(R, -20, 20), c = nz(R, -20, 20), d = nz(R, -9, 9);
  const L = R.shuffle([[`${zS(a)} · ${zP(c)} ${isq} ${zS(c)} · ${zP(a)}`, 'w'], [`(${zS(c)} + ${zP(d)}) + ${zP(a)} ${isq} ${zS(c)} + (${zS(d)} + ${zP(a)})`, 's'],
    [`${zS(d)} + 0 ${isq} ${zS(d)}`, 'n'], [`${zS(-a)} + ${zP(a)} ${isq} 0`, 'y'], [`0 · ${zP(c)} ${isq} 0`, 'o'], [`1 · ${zP(a)} ${isq} ${zS(a)}`, 'n']]).slice(0, 4);
  const g = el('div', 'm4-items een'); b.append(g);
  L.forEach(([h, ans], i) => { const row = el('div', 'm4-wn'); g.append(row); qChoice(row, st, save, 'e' + i, { nr:'abcd'[i] + ')', html:`<span class="m5-groot">${h}</span>`, opts:EIG5, ans }); });
  st._show = L.map(([, a], i) => `${'abcd'[i]}) ${EIG5.find(o => o[0]===a)[1]}`).join(' · ');
}, null, 'Module 5 › Eigenschappen');
E2.lijn = pexV('Lijndiagram', 2, '', (b, st, save, key) => {
  const R = makeR(st); const item = M3.POOL[2].fixed[R.pick([1, 3, 5])];
  viaMod(M3, item).build(b, st, save, key); st._show = item.show;
}, null, 'Module 3 › Lijndiagrammen');
E2.waar = pexV('Waar of niet waar?', 3, 'Is de uitspraak waar of niet waar? Geef bij “niet waar” een tegenvoorbeeld: een geheel getal waarvoor de uitspraak niet klopt.', (b, st, save) => {
  const R = makeR(st);
  const NW = R.shuffle([
    ['Als je bij een geheel getal 4 optelt, is de som altijd positief.', a => a + 4 > 0, 'bv. −10: −10 + 4 = −6'],
    ['Als je een geheel getal met −1 vermenigvuldigt, krijg je altijd een negatief getal.', a => a*-1 < 0, 'bv. −3: −3 · (−1) = 3'],
    ['Het tegengestelde van een geheel getal is altijd kleiner dan 0.', a => -a < 0, 'bv. −5: het tegengestelde is 5'],
    ['Als je een geheel getal van 0 aftrekt, is het verschil altijd negatief.', a => 0 - a < 0, 'bv. −2: 0 − (−2) = 2']]);
  const W = R.shuffle([
    ['Het product van twee negatieve gehele getallen is altijd positief.', null, 'min maal min is plus'],
    ['Als je van een negatief getal een positief getal aftrekt, is het verschil altijd negatief.', null, 'je gaat nog verder naar links op de getallenas'],
    ['De absolute waarde van een geheel getal is nooit negatief.', null, 'de absolute waarde is een afstand tot 0']]);
  const P = R.shuffle([NW[0], NW[1], W[0]]);
  P.forEach(([t, f], i) => qBlock(b, st, save, 'w' + i, { nr:'abc'[i] + ')', html:`<span class="stmt">${t}</span>`, choice:[['w', 'waar'], ['n', 'niet waar']], html2:'Tegenvoorbeeld (als het niet waar is): [[0:xs]]', allowEmpty:true,
    check:(v, c) => { if(!f) return c==='w' ? {ok:true, choiceOk:true} : {ok:false, choiceOk:false}; if(c!=='n') return {ok:false, choiceOk:false}; const x = pexGetal(v[0]); if(isNaN(x) || !Number.isInteger(x)) return {ok:false, choiceOk:true, msg:'Geef een geheel getal als tegenvoorbeeld.'}; return f(x) ? {ok:false, choiceOk:true, msg:'Voor dat getal klopt de uitspraak wel.'} : {ok:true, choiceOk:true}; } }));
  st._show = P.map(([t, f, uit], i) => `${'abc'[i]}) ${f ? 'niet waar, ' + uit : 'waar: ' + uit}`).join(' · ');
}, null, 'Module 5 › Alles door elkaar');

/* ---------- Deel 2 ---------- */
E2.as = pexV('De getallenas', 2, 'Denk aan de getallenas.', (b, st, save) => {
  const R = makeR(st); const a = -R.int(6, 15)*2, c = R.int(1, 8)*2, s = nz(R, -9, 5), j = R.int(4, 12), u = R.int(2, 9);
  const L = [[`Welk getal ligt precies in het midden tussen ${zS(a)} en ${zS(c)}?`, (a + c)/2], [`Welk getal ligt ${j} eenheden links van ${zS(s)}?`, s - j],
    [`Hoeveel eenheden liggen ${zS(a)} en ${zS(c)} uit elkaar?`, c - a], [`Welke gehele getallen hebben een absolute waarde van ${u}? Geef het negatieve.`, -u]];
  L.forEach(([t, T], i) => mQ(b, st, save, 'a' + i, { nr:'abcd'[i] + ')', html:`<span class="txt">${t}</span> {{u:a}}`, check:V => chkG(V.a, T) }));
  st._show = L.map(([, T], i) => `${'abcd'[i]}) ${zS(T)}`).join(' · ');
}, null, 'Module 5 › Ordenen en de getallenas');
E2.symbolen = pexV('∈, ∉, ⊂, ⊄ of = in een figuur', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.symbolen).build(b, st, save, key), null, 'Module 2 › ∈ ∉ ⊂ ⊄ =');
E2.tekenHoek = pexPapier(pexV('Hoeken tekenen', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.tekenHoek).build(b, st, save, key), null, 'Module 2 › Hoeken tekenen'));
E2.insp = pexPapier(pexV('Inspringende hoek', 1.5, '', (b, st, save, key) => viaMod(M2, M2.TQ.insmeten).build(b, st, save, key), null, 'Module 2 › Inspringende hoeken'));
E2.bis = pexPapier(pexV('Bissectrice', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.bistek).build(b, st, save, key), null, 'Module 2 › Bissectrice'));
E2.freq = pexV('Frequentietabel', 3, '', (b, st, save, key) => {
  const R = makeR(st); const item = M3.POOL[4].gen(R.f);
  viaMod(M3, item).build(b, st, save, key); st._show = item.show;
}, null, 'Module 3 › Frequentietabel');
E2.aanvul = pexV('Welk getal ontbreekt?', 3, 'Zoek telkens het ontbrekende natuurlijk getal. Werk op je kladblad.', (b, st, save) => {
  const R = makeR(st);
  /* gemiddelde */
  const g = R.int(7, 9), L1 = [g - R.int(1, 4), g + R.int(1, 4), g + R.int(0, 3)]; const x1 = 4*g - L1.reduce((p, x) => p + x, 0);
  /* mediaan bij 6 gegevens: twee middelste rond een gegeven mediaan */
  const m = R.int(10, 20), L2 = [m - R.int(5, 8), m - R.int(1, 3), m + 1 + R.int(2, 5), m + 1 + R.int(6, 9), m + 1 + R.int(10, 12)].sort((p, q) => p - q); const x2 = 2*m - L2[1];
  /* variatiebreedte: het nieuwe getal is het grootste */
  const L3 = R.shuffle([R.int(3, 6), R.int(7, 10), R.int(11, 14)]); const vb = R.int(15, 20); const x3 = Math.min(...L3) + vb;
  const Q = [[`Het gemiddelde van ${L1.join(', ')} en ▢ is ${g}.`, x1], [`De mediaan van ${R.shuffle(L2).join(', ')} en ▢ is ${m}. (▢ is niet het grootste of het kleinste getal.)`, x2], [`De variatiebreedte van ${L3.join(', ')} en ▢ is ${vb}.`, x3]];
  Q.forEach(([t, T], i) => qBlock(b, st, save, 'q' + i, { nr:'abc'[i] + ')', html:`${t} &nbsp; ▢ = [[0:xs]]`, mode:'numeric', check:pexIs(T) }));
  st._show = `a) ${x1} (som = 4 · ${g} = ${4*g}) · b) ${x2} (de twee middelste getallen ${L2[1]} en ${x2} hebben ${m} als gemiddelde) · c) ${x3} (${x3} − ${Math.min(...L3)} = ${vb})`;
}, null, 'Module 3 › Het gemiddelde, De mediaan en Variatiebreedte');
E2.interp = pexV('Data interpreteren', 2, '', (b, st, save, key) => {
  const R = makeR(st); const i = R.pick([1, 4]); const j = R.pick([2, 5]);
  const A = M3.POOL[10].fixed[i], B = M3.POOL[10].fixed[j];
  viaMod(M3, A).build(b, st, save, key + 'a'); viaMod(M3, B).build(b, st, save, key + 'b');
  st._show = A.show + ' · ' + B.show;
}, null, 'Module 3 › Data interpreteren');
E2.kgv3 = pexV('Vraagstuk', 2, '', (b, st, save) => {
  const R = makeR(st); const T = R.pick([[4, 6, 10], [3, 4, 10], [6, 8, 12], [4, 5, 6], [6, 9, 12]]); const k = T.reduce(pexKgv);
  const dg = ['maandag', 'dinsdag', 'woensdag', 'donderdag', 'vrijdag', 'zaterdag', 'zondag']; const d0 = R.int(0, 6);
  b.append(el('div', 'q-text block', `Sara gaat om de ${T[0]} dagen zwemmen, Tim om de ${T[1]} dagen en Lies om de ${T[2]} dagen. Op ${dg[d0]} zwemmen ze alle drie samen.`));
  qBlock(b, st, save, 'a', { nr:'a)', html:'Na hoeveel dagen zwemmen ze opnieuw alle drie samen? [[0:xs]] dagen', mode:'numeric', pts:1.5, check:pexIs(k) });
  qChoice(b, st, save, 'd', { nr:'b)', html:'Welke dag van de week is dat?', opts:dg.map(d => [d, d]), ans:dg[(d0 + k) % 7], pts:.5 });
  st._show = `kgv(${T.join(', ')}) = ${k} dagen · ${dg[(d0 + k) % 7]}`;
}, null, 'Module 1 › Vraagstukken');
E2.gem = pexV('Vraagstuk met het gemiddelde', 2, '', (b, st, save) => {
  const R = makeR(st); const doel = R.int(13, 16); const L = [doel + R.int(-3, 3), doel + R.int(-3, 2), doel + R.int(-2, 3), doel + R.int(-4, 1)]; const x = 5*doel - L.reduce((p, y) => p + y, 0);
  if(x > 20 || x < 0){ L[3] = 5*doel - L[0] - L[1] - L[2] - 17; }
  const x2 = 5*doel - L.reduce((p, y) => p + y, 0);
  b.append(el('div', 'q-text block', `Lien haalde op vier toetsen ${L.join(', ')} op 20. Er komt nog één toets op 20.`));
  qBlock(b, st, save, 'a', { nr:'a)', html:'Wat is haar gemiddelde na vier toetsen? [[0:xs]] op 20', pts:1, check:pexIs(L.reduce((p, y) => p + y, 0)/4, .001) });
  qBlock(b, st, save, 'b', { nr:'b)', html:`Hoeveel moet ze op de vijfde toets halen om gemiddeld ${doel} op 20 te hebben? [[0:xs]] op 20`, mode:'numeric', pts:1, check:pexIs(x2) });
  st._show = `a) ${L.join(' + ')} = ${L.reduce((p, y) => p + y, 0)}, : 4 = ${pexKomma(L.reduce((p, y) => p + y, 0)/4)} · b) 5 · ${doel} = ${5*doel}, ${5*doel} − ${L.reduce((p, y) => p + y, 0)} = ${x2}`;
}, null, 'Module 3 › Het gemiddelde');
PEX.examens.push({
  deel1:[E2.impl, E2.deelbaar, E2.kleur, E2.pf, E2.ggd, E2.teken, E2.ontbreek, E2.eig, E2.lijn, E2.waar],
  deel2:[E2.as, E2.symbolen, E2.tekenHoek, E2.insp, E2.bis, E2.freq, E2.aanvul, E2.interp, E2.kgv3, E2.gem]
});


/* ===== pex_30_examen3.js ===== */
/* ============================================================
   PROEFEXAMEN 3
   ============================================================ */
const E3 = {};
/* ---------- Deel 1 ---------- */
E3.roos = pexV('Soorten getallen', 2, '', (b, st, save, key) => {
  const R = makeR(st); const a = R.int(2, 9), q = R.int(2, 6);
  const L = R.shuffle([[String(R.int(3, 40)), 'N'], [String(-R.int(2, 30)), 'Z'], [`${R.int(1, 9)}/${R.pick([4, 7, 9, 11])}`, 'Q'], [`${a*q}/${q}`, 'N'], [`-${a*q}/${q}`, 'Z'], [`-${R.int(1, 9)},${R.int(1, 9)}`, 'Q']]);
  const item = M1.PQ.roos(L); viaMod(M1, item).build(b, st, save, key); st._show = item.show;
}, null, 'Module 1 › Soorten getallen');
E3.element = pexV('∈ of ∉', 2, 'Vul in met ∈ of ∉.', (b, st, save) => {
  const R = makeR(st); const k = R.pick([4, 6, 7, 8]), n = R.pick([36, 40, 48, 60]), d = pexDelers(n);
  const L = R.shuffle([[`${R.pick(d.slice(1, -1))} … del ${n}`, 'in'], [`${n + R.pick([2, 3, 4])} … del ${n}`, 'uit'], [`0 … ${k}ℕ`, 'in'], [`${k*R.int(3, 9) + 1} … ${k}ℕ`, 'uit'], [`${zS(-k)} … ${k}ℕ`, 'uit'], [`${k*R.int(10, 15)} … ${k}ℕ`, 'in']]).slice(0, 4);
  const g = el('div', 'm4-items'); b.append(g);
  L.forEach(([h, a], i) => { const row = el('div', 'm4-wn'); g.append(row); qChoice(row, st, save, 'e' + i, { nr:'abcd'[i] + ')', html:`<span class="m5-groot">${h}</span>`, sym:true, opts:[['in', '∈'], ['uit', '∉']], ans:a }); });
  st._show = L.map(([h, a]) => h.replace('…', a==='in' ? '∈' : '∉')).join(' · ');
}, null, 'Module 1 › ∈ of ∉');
E3.bewerk = pexV('Bewerkingen met verzamelingen', 3, '', (b, st, save) => {
  const R = makeR(st); const n = R.pick([12, 18, 20, 30]), k = R.pick([2, 3, 4, 5]), g = R.pick([20, 25, 30]);
  const A = pexDelers(n), B = Array.from({length:Math.floor((g - 1)/k) + 1}, (_, i) => i*k).filter(x => x < g);
  const U = [...new Set(A.concat(B))].sort((p, q) => p - q), D = A.filter(x => B.includes(x)), V = A.filter(x => !B.includes(x));
  b.append(el('div', 'q-text block', `<div class="given-box"><b>Gegeven:</b> A = del ${n} en B = {x ∈ ${k}ℕ | x &lt; ${g}}</div>Noteer door opsomming.`));
  [['A ∩ B', D], ['A \\ B', V], ['A ∪ B', U]].forEach(([l, T], i) => qBlock(b, st, save, 'v' + i, { nr:'abc'[i] + ')', html:`<span class="stmt">${l} =</span> { [[0:wide]] }`, check:pexVerzIs(T) }));
  st._show = `A = {${A.join(', ')}}, B = {${B.join(', ')}} · A ∩ B = {${D.join(', ')}} · A \\ B = {${V.join(', ')}} · A ∪ B = {${U.join(', ')}}`;
}, null, 'Module 1 › Opsomming en Venn');
E3.ggdpf = pexV('ggd en kgv met priemfactoren', 2, '', (b, st, save) => {
  const R = makeR(st); const [a, c] = R.pick([[90, 84], [60, 126], [72, 120], [150, 84], [66, 110]]);
  b.append(el('div', 'q-text block', `Gegeven: <b>${a} = ${pexPfT(a)}</b> en <b>${c} = ${pexPfT(c)}</b>.`));
  qBlock(b, st, save, 'g', { nr:'a)', html:`ggd(${a}, ${c}) = [[0:xs]]`, mode:'numeric', check:pexIs(ggd(a, c)) });
  qBlock(b, st, save, 'k', { nr:'b)', html:`kgv(${a}, ${c}) = [[0:xs]]`, mode:'numeric', check:pexIs(pexKgv(a, c)) });
  st._show = `ggd = ${pexPfT(ggd(a, c))} = ${ggd(a, c)} (de gemeenschappelijke factoren) · kgv = ${pexPfT(pexKgv(a, c))} = ${pexKgv(a, c)}`;
}, null, 'Module 1 › ggd en kgv');
E3.situaties = pexV('Gehele getallen in situaties', 2, 'Schrijf een bewerking en reken uit. Elke stap op een nieuwe regel met =.', (b, st, save) => {
  const R = makeR(st); const s = R.int(15, 60), k = R.int(2, 4)*10, n = R.int(2, 4), d = R.int(3, 8)*3, m = R.int(2, 4);
  const L = [[`Op de bankapp van Ella staat € ${s}. Ze koopt ${n} concerttickets van € ${k} per stuk. Hoeveel staat er daarna op haar rekening?`, `${s} − ${n} · ${k}`, 'euro'],
    [`Een duikboot vaart op ${zS(-d)} m. Hij duikt ${m} keer ${d} m dieper. Op welke diepte vaart hij dan?`, `${zS(-d)} − ${m} · ${d}`, 'm']];
  const g = el('div', 'm4-items een'); b.append(g);
  L.forEach(([tx, E, eh], i) => { const T = ZX.waarde(E); mQ(g, st, save, 'v' + i, { nr:'ab'[i] + ')', html:`<span class="txt">${tx}</span> {{z:a,mdh}}`, check:V => chkZ(V.a, T) }); });
  st._show = L.map(([, E, eh]) => `${zT(E)} = ${zS(ZX.waarde(E))} ${eh}`).join(' · ');
}, null, 'Module 5 › Alles door elkaar');
E3.gedur = pexV('Gedurige som en product', 2, 'Reken handig uit. Schrijf elke tussenstap op een nieuwe regel met =.', (b, st, save) => {
  const R = makeR(st); const t = () => R.int(2, 25);
  let s = zS(-t()); for(let j=0; j<4; j++) s += ` ${R.pick(['+', '−'])} ${zP(R.sign()*t())}`;
  const p = R.shuffle([R.pick([-2, -4, 25]), R.int(2, 9)*R.sign(), -R.pick([5, 50]), R.int(2, 6)]).map((x, k) => k ? zP(x) : zS(x)).join(' · ');
  pexRij(b, 2, (g, i, nr) => vrijOpg(g, st, save, 'g' + i, nr, i ? p : s, {k:'mdh', hint:false}), {een:true});
  st._show = `${zT(s)} = ${zS(ZX.waarde(s))} · ${zT(p)} = ${zS(ZX.waarde(p))}`;
}, null, 'Module 5 › Gedurige som en product');
E3.distr = pexV('Distributiviteit', 2, 'Werk de haakjes weg of reken handig. Schrijf elke tussenstap op een nieuwe regel met =.', (b, st, save) => {
  const R = makeR(st); const x = R.pick(['x', 'y', 'b']), n = R.int(2, 9), m = R.int(2, 9), a = R.int(3, 12);
  const E = R.pick([`-${n} · (${x} + ${m})`, `${n} · (${m} - ${x})`, `-${n} · (-${x} + ${m})`]); const r = R.pick([101, 98, 102]);
  pexRij(b, 2, (g, i, nr) => i ? mQ(g, st, save, 'h', { nr, html:`<span class="m5-opg">${r} · ${zP(-a)}</span> {{z:a,mdh}}`, check:V => chkZ(V.a, -a*r) }) : letterOpg(g, st, save, 'l', nr, E, false), {een:true});
  st._show = `${ltH(E)} = ${ZX.H(ZX.waarde(E))} · ${r} · ${zP(-a)} = (100 ${r<100 ? '−' : '+'} ${Math.abs(r - 100)}) · ${zP(-a)} = ${zS(-a*r)}`;
}, null, 'Module 5 › Distributiviteit');
E3.fout = pexV('Zoek de fout', 2, 'In elke uitwerking zit één fout. Klik op de eerste stap die fout is.', (b, st, save) => {
  const R = makeR(st);
  const a = nz(R, -9, 9), c = R.int(2, 6), d = -R.int(2, 7); const E1_ = `${zS(a)} + ${c} · ${zP(d)}`; const goed = a + c*d;
  const f1 = { task:`Bereken ${E1_}`, lines:[`= ${zS(a + c)} · ${zP(d)}`, `= ${zS((a + c)*d)}`], wrong:0, why:'Eerst vermenigvuldigen, dan optellen.' };
  if((a + c)*d===goed) f1.lines = [`= ${zS(a)} + ${zP(c*d)}`, `= ${zS(goed + 2)}`], f1.wrong = 1;
  const p = R.int(10, 30), q = R.int(31, 60), r2 = R.int(2, 9);
  const f2 = { task:`Bereken ${zS(p)} − ${q} − ${zP(-r2)}`, lines:[`= ${zS(p)} + ${zP(-q)} + ${zP(r2)}`, `= ${zS(p - q)} + ${zP(r2)}`, `= ${zS(p - q - r2)}`], wrong:2, why:'Het tegengestelde van −' + r2 + ' is +' + r2 + ', dus je telt op.' };
  const F = R.shuffle([f1, f2]);
  F.forEach((f, i) => errBlock(b, st, save, 'f' + i, Object.assign({nr:'ab'[i] + ')'}, f)));
  st._show = F.map((f, i) => `${'ab'[i]}) stap ${f.wrong + 1}: ${f.why}`).join(' · ');
}, null, 'Module 5 › Zoek de fout');
E3.cirkel = pexV('Cirkeldiagram', 2.5, '', (b, st, save) => {
  const R = makeR(st); const N = R.pick([400, 500, 600, 800]);
  const P = R.pick([[45, 30, 15, 10], [40, 35, 20, 5], [50, 25, 15, 10], [35, 30, 25, 10]]);
  const lab = ['fiets', 'bus', 'te voet', 'auto'];
  const [l, r] = pexNaast(b);
  l.append(el('div', 'q-text block', `Alle ${N} leerlingen van een school vertelden hoe ze naar school komen.`));
  pexGrafiek(l, 'cirkel', {labels:lab, series:[{values:P}], title:'Hoe kom je naar school?'});
  lab.forEach((t, i) => qBlock(r, st, save, 'c' + i, { nr:'abcd'[i] + ')', html:`Aantal leerlingen dat met ${t==='te voet' ? 'te voet komt' : 'de ' + t + ' komt'}: [[0:xs]]`, mode:'numeric', check:pexIs(N*P[i]/100) }));
  st._show = lab.map((t, i) => `${t}: ${P[i]} % van ${N} = ${N*P[i]/100}`).join(' · ');
}, null, 'Module 3 › Diagrammen');
E3.raadsel = pexV('Raadsel', 2, '', (b, st, save) => {
  const R = makeR(st); const g = R.int(101, 989);
  b.append(el('div', 'q-text block', `Noor neemt een getal van drie cijfers, bijvoorbeeld ${g}. Ze schrijft het getal twee keer na elkaar: <b>${dz(String(g*1001))}</b>. Dat doet ze met elk getal van drie cijfers.`));
  qBlock(b, st, save, 'a', { nr:'a)', html:'Met welk getal heeft ze haar getal eigenlijk vermenigvuldigd? [[0:xs]]', mode:'numeric', check:pexIs(1001) });
  multiKeuze(b, st, save, 'b', { nr:'b)', html:'Het nieuwe getal is <b>altijd</b> deelbaar door … (duid alle juiste aan; tip: 1001 = 7 · 11 · 13)', opts:[['2', '2', false], ['7', '7', true], ['11', '11', true], ['13', '13', true], ['10', '10', false]] });
  st._show = `${g} · 1001 = ${dz(String(g*1001))}; 1001 = 7 · 11 · 13, dus altijd deelbaar door 7, 11 en 13`;
}, null, 'Module 1 › Welke getallen?');

/* ---------- Deel 2 ---------- */
E3.vgl = pexV('Vergelijken', 2, 'Vul in met &lt;, = of &gt;.', (b, st, save) => {
  const R = makeR(st); const a = R.int(2, 15), c = R.int(2, 15), d = R.int(2, 9), e = R.int(2, 9);
  const L = R.shuffle([[`|${zS(-a)}|`, a, `−(${zS(-a)})`, a], [`${zS(-c)}`, -c, `−|${zS(c + 2)}|`, -(c + 2)], [`|${zS(d - 12)}|`, Math.abs(d - 12), `${zS(-d)} + 12`, 12 - d], [`−(+${e})`, -e, `|${zS(-e)}| − ${2*e}`, -e]]);
  const g = el('div', 'm4-items'); b.append(g);
  L.forEach(([h1, w1, h2, w2], i) => { const row = el('div', 'm4-wn'); g.append(row); qChoice(row, st, save, 'v' + i, { nr:'abcd'[i] + ')', html:`<span class="m5-groot">${h1} … ${h2}</span>`, sym:true, opts:VGL, ans:w1 < w2 ? '<' : w1 > w2 ? '>' : '=' }); });
  st._show = L.map(([h1, w1, h2, w2]) => `${h1} ${w1 < w2 ? '&lt;' : w1 > w2 ? '&gt;' : '='} ${h2}`).join(' · ');
}, null, 'Module 5 › Absolute waarde en Ordenen');
E3.snij = pexV('Snijpunten en collineaire punten', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.snij).build(b, st, save, key), null, 'Module 2 › Collineair en concurrent');
E3.constr = pexPapier(pexV('Construeren', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.constr).build(b, st, save, key), null, 'Module 2 › Construeren'));
E3.soorten = pexV('Soorten hoeken', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.soorten).build(b, st, save, key), null, 'Module 2 › Soorten hoeken');
E3.reden = pexV('Hoeken berekenen met een reden', 2, '', (b, st, save, key) => viaMod(M2, M2.TQ.reden).build(b, st, save, key), null, 'Module 2 › Hoeken berekenen');
