E3.prijs = pexV('Vraagstuk met een prijslijst', 2.5, '', (b, st, save) => {
  const R = makeR(st);
  const PR = [['bolletje ijs', 1.6], ['hoorntje', 0.5], ['potje', 0.3], ['slagroom', 0.8], ['milkshake', 3.9]];
  const n = R.int(3, 6), bol = R.int(2, 3), ms = R.int(1, 2); const hoorn = n - R.int(1, 2), pot = n - hoorn;
  const T = n*bol*1.6 + hoorn*0.5 + pot*0.3 + ms*3.9; const B = T <= 50 ? 50 : 100;
  const [l, r] = pexNaast(b);
  l.append(el('div', '', `<table class="pex-tabel"><tr><th class="l" colspan="2">IJssalon Pinguïn</th></tr>${PR.map(([t, p]) => `<tr><td class="l">${t}</td><td>${pexEuro(p)}</td></tr>`).join('')}</table>`));
  r.append(el('div', 'q-text block', `${n} vrienden nemen elk een ijsje met ${bol} bolletjes: ${hoorn} in een hoorntje en ${pot} in een potje. Ze drinken samen ook ${ms} milkshake${ms > 1 ? 's' : ''}.`));
  qBlock(r, st, save, 'a', { nr:'a)', html:'Hoeveel betalen ze samen? € [[0:xs]]', pts:1.5, check:pexIs(T, .001) });
  qBlock(r, st, save, 'b', { nr:'b)', html:`Ze betalen met een briefje van ${B} euro. Hoeveel krijgen ze terug? € [[0:xs]]`, pts:1, check:pexIs(B - T, .001) });
  st._show = `${n} · ${bol} · 1,60 + ${hoorn} · 0,50 + ${pot} · 0,30 + ${ms} · 3,90 = ${pexEuro(T)} · terug: ${pexEuro(B - T)}`;
}, null, 'Module 5 › Alles door elkaar en vraagstukken');
E3.code = pexV('Kraak de code', 3, '', (b, st, save) => {
  const R = makeR(st); let s;
  /* vijf scores: modus, mediaan, gemiddelde en variatiebreedte zijn gehele getallen en geven cijfers van 0 tot 9 */
  for(let t=0; t<500; t++){ const m = R.int(12, 16); const v = [m, m, m + R.int(1, 3), m - R.int(2, 5), m + R.int(4, 8)]; const som = v.reduce((p, x) => p + x, 0);
    const so = v.slice().sort((p, q) => p - q); const vb = so[4] - so[0]; if(som % 5===0 && vb % 2===0 && so[2]===m){ s = {v:R.shuffle(v), m, gem:som/5, med:so[2], vb}; break; } }
  if(!s) s = {v:[14, 14, 16, 10, 21], m:14, gem:15, med:14, vb:11 + 1};
  const naam = ['Amir', 'Bo', 'Cas', 'Dina', 'Elif'];
  b.append(el('div', 'q-text block', `De kluis van de klas heeft een code van vier cijfers. Vijf vrienden scoren in een spel: ${s.v.map((x, i) => `${naam[i]} ${x}`).join(', ')} punten.`));
  const C = [[`Cijfer 1 = de modus − 10`, s.m - 10], [`Cijfer 2 = de mediaan − 9`, s.med - 9], [`Cijfer 3 = het gemiddelde − 8`, s.gem - 8], [`Cijfer 4 = de helft van de variatiebreedte`, s.vb/2]].map(([t, T]) => [t, ((T % 10) + 10) % 10]);
  C.forEach(([t, T], i) => qBlock(b, st, save, 'c' + i, { html:`${t} &nbsp; [[0:xs]]`, mode:'numeric', pts:.6, check:pexIs(T) }));
  qBlock(b, st, save, 'code', { html:'De code is [[0]]', mode:'numeric', pts:.6, check:v => ({ok:String(v[0]).replace(/\s/g, '')===C.map(c => c[1]).join('')}) });
  st._show = `modus ${s.m}, mediaan ${s.med}, gemiddelde ${s.gem}, variatiebreedte ${s.vb} · code ${C.map(c => c[1]).join('')}`;
}, null, 'Module 3 › Modus, Het gemiddelde, De mediaan, Variatiebreedte');
PEX.examens.push({
  deel1:[E3.roos, E3.element, E3.bewerk, E3.ggdpf, E3.situaties, E3.gedur, E3.distr, E3.fout, E3.cirkel, E3.raadsel],
  deel2:[E3.vgl, E3.snij, E3.constr, E3.soorten, E3.reden, E3.toestel, E3.soortdata, E3.krant, E3.prijs, E3.code]
});


/* ===== pex_99_opbouw.js ===== */
/* ============================================================
   OPBOUW VAN DE SITE · drie proefexamens in het menu links
   ============================================================ */
const PEX_TIP = 'Een proefexamen in twee delen, zoals het echte examen: <b>Deel 1</b> zonder rekentoestel en <b>Deel 2</b> met rekentoestel. Werk op kladpapier, zonder spiekbriefje. Je krijgt pas feedback als je onderaan een deel op <b>Verbeter</b> klikt; daarna zie je bij elke fout het juiste antwoord. Met <b>↺ Opnieuw met andere getallen</b> krijg je dezelfde soort vragen met nieuwe getallen.';
const SECTIONS = PEX.examens.map((ex, i) => ({ id:'toets' + (i+1), ic:'toets', nav:'Proefexamen ' + (i+1), title:'Proefexamen ' + (i+1), ex }));
if(window.CL_VERBORGEN){ for(let i = SECTIONS.length - 1; i >= 0; i--) if(window.CL_VERBORGEN.has(SECTIONS[i].id)) SECTIONS.splice(i, 1); }
const app = document.getElementById('app');
const nav = document.getElementById('nav');
const pager = document.getElementById('pager');
const renderers = {};
const secEls = {}, navLinks = {}, secBuilt = {};
(function(){ const s = document.createElement('style'); s.textContent = `
  .pex-tot{ margin:.4rem 0 .8rem; }
  .pex-tot-t{ margin:0; padding:.7rem 1rem; border-radius:.8rem; background:var(--accent-soft); }
  .pex-tijd{ margin:.6rem 0 .2rem; font-weight:700; color:var(--accent-dark); }
  .pex-q{ margin-top:1.1rem; }
  .pex-prompt{ margin:.3rem 0 .5rem; }
  .pex-waar{ display:block; margin-top:.3rem; font-size:.92em; color:var(--ink-soft); }
  .pex-naast{ display:grid; grid-template-columns:minmax(0, 1fr) minmax(0, 1fr); gap:1rem 1.4rem; align-items:start; }
  .pex-naast > *{ min-width:0; }
  @media (max-width:760px){ .pex-naast{ grid-template-columns:minmax(0, 1fr); } }
  .pex-tabel{ border-collapse:collapse; margin:.3rem 0; }
  .pex-tabel th, .pex-tabel td{ border:1px solid var(--accent); padding:.3rem .6rem; text-align:center; }
  .pex-tabel th{ background:var(--accent-soft); }
  .pex-tabel td.l, .pex-tabel th.l{ text-align:left; }
  .pex-code{ display:flex; gap:.4rem; flex-wrap:wrap; }
  .pex-tip{ margin:.2rem 0; }
  .pex-papier{ margin:.3rem 0 .6rem; padding:.55rem .9rem; border-radius:.7rem; border:2px solid #FCAF17; background:#FFF4DC; color:#5a3d00; }
`; document.head.append(s); })();

function buildSection(sec, num){
  const s = secEls[sec.id];
  s.append(el('div', 'sec-head', `<span class="sec-ic">${icon(sec.ic)}</span><h2><span class="num">${num}.</span>${sec.title}</h2>`));
  s.append(el('div', 'tip', icon('bulb') + `<div>${PEX_TIP}</div>`));
  const c = el('div', 'card m4-geenbrk'); s.append(c);
  try{ pexExamen(c, num, sec.ex); }catch(err){ console.error(err); c.append(el('p', 'fb bad', 'Er liep iets mis bij het maken van dit proefexamen.')); }
}
SECTIONS.forEach((sec, si) => {
  const num = +sec.id.slice(5);
  const li = el('li');
  const a = el('button', '', `${icon(sec.ic)}<span class="n">${si+1}</span><span class="lbl">${sec.nav}</span>`);
  a.type = 'button'; a.addEventListener('click', () => show(sec.id, true));
  li.append(a); nav.append(li); navLinks[sec.id] = a;
  const s = el('section', 'group'); s.id = sec.id; s.hidden = true;
  app.append(s); secEls[sec.id] = s; sec.num = num;
});
function show(id, scroll){
  const idx = SECTIONS.findIndex(s => s.id===id); if(idx<0) return;
  clearSel();
  if(!secBuilt[id]){ secBuilt[id] = true; buildSection(SECTIONS[idx], SECTIONS[idx].num); }
  SECTIONS.forEach(s => { secEls[s.id].hidden = s.id!==id; navLinks[s.id].removeAttribute('aria-current'); });
  navLinks[id].setAttribute('aria-current', 'page');
  /* het rekentoestel volgt het actieve deel van het getoonde examen */
  const d2 = secEls[id].querySelector('.tabs .tab[aria-selected="true"]'); pexToestel(!!d2 && /Deel 2/.test(d2.textContent));
  pager.innerHTML = '';
  if(idx>0){ const p = SECTIONS[idx-1]; const b = el('button', 'prev', `<small>← Vorige</small>${idx}. ${p.nav}`); b.type = 'button'; b.addEventListener('click', () => show(p.id, true)); pager.append(b); }
  if(idx<SECTIONS.length-1){ const n = SECTIONS[idx+1]; const b = el('button', 'next', `<small>Volgende →</small>${idx+2}. ${n.nav}`); b.type = 'button'; b.addEventListener('click', () => show(n.id, true)); pager.append(b); }
  try{ localStorage.setItem(PREFIX + 'tab', id); }catch(e){}
  if(scroll) window.scrollTo({top:0, behavior:'smooth'});
}
if(SECTIONS.length){
  let startId = SECTIONS[0].id;
  try{ const h = location.hash.slice(1); const t = localStorage.getItem(PREFIX + 'tab'); if(secEls[h]) startId = h; else if(t && secEls[t]) startId = t; }catch(e){}
  show(startId, false);
}
